SELECT COUNT(DISTINCT a.hadm_id) AS num_admissions FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'F' AND p.anchor_year = 51 AND p.anchor_year_group BETWEEN 46 AND 56 AND t.eventtype = 'transfer' AND d.icd_code = '777071' AND a.admission_type = 'I';